'use strict';
const HousingUI=(()=>{
 const num=n=>n.toLocaleString('th-TH',{maximumFractionDigits:0});
 function panel(s){const h=Housing.ensure(s);return `<button class="panel housing-overview" id="openHousing"><span class="eyebrow">ถิ่นพักและสิ่งที่ต้องดูแล</span><strong>${h.owned?esc(Housing.option(s,h.tier).name):RaceDrives.cashless(s)?'พักในถิ่นที่กลุ่มดูแลร่วมกัน':'ยังแบ่งที่พักกับครอบครัวหรือเช่าอยู่'}</strong><span>${h.owned?Housing.option(s,h.tier).annual.toLocaleString('th-TH')+' '+(h.native?'แหล่งถิ่น':'ทอง')+' ต่อปี':'เลือกดูระดับที่พักและภาระรายปี'} · ดูที่พัก ↗</span></button>`}
 function open(){const s=state,h=Housing.ensure(s),native=RaceDrives.cashless(s);modal(`<section class="housing-dialog"><span class="eyebrow">ปี ${WorldTimeline.year(s)} · ที่พักของชีวิตนี้</span><h2>${h.owned?esc(Housing.option(s,h.tier).name):'ที่ที่อยากกลับมาพัก'}</h2><p>${native?'ความกว้างของเขตพักใช้ทั้งสิทธิร่วมถิ่น แหล่งดำรงชีวิต และแรงดูแลต่อเนื่อง':'ซื้อสดหรือขายที่พักเดิมสมทบเมื่อขยับระดับ ค่าภาษี ประกันและบำรุงคิดทุกปี แบ่งจ่ายตามเวลาที่ผ่านไป'}</p><p>${native?'แหล่งถิ่น '+Math.round(s.raceDrives.resource)+'/100':'เงินพร้อมใช้ '+num(s.gold)+' ทอง'+(h.owned?' · ที่พักเดิมขายสุทธิได้ '+num(Housing.value(s))+' ทอง':'')}</p><div class="housing-options">${Housing.catalog.map((_,i)=>{const o=Housing.option(s,i),why=Housing.reason(s,i);return `<article class="${h.tier===i?'current':''}"><canvas width="160" height="72" data-home-preview="${i}" role="img" aria-label="ที่พักระดับ ${i+1}"></canvas><span class="eyebrow">ระดับ ${i+1}/5</span><h3>${esc(o.name)}</h3><p>${native?'พื้นที่พักและจุดหลบเพิ่มตามรูปกาย ต้องคุ้มครองและฟื้นแหล่งถิ่น':' '+esc(o.description)}</p><strong>${num(o.cost)} ${o.unit}</strong><p class="housing-upkeep">ภาระรายปี ${num(o.annual)} ${o.unit}</p>${why?`<small>${esc(why)}</small>`:''}<button class="secondary" data-buy-housing="${i}" ${why?'disabled':''}>${h.owned?'ขายที่พักเดิมและขยับระดับ':'จัดที่พักระดับนี้'}</button></article>`}).join('')}</div>${h.owned&&!h.native?`<button class="secondary" id="sellHousing" ${!LifeSpending.allowed(s)||Engine.biological(s)<18?'disabled':''}>ตรวจสอบการขายที่พักเดิม →</button>`:''}</section>`);document.querySelectorAll('[data-buy-housing]').forEach(b=>b.onclick=()=>{if(Housing.buy(s,Number(b.dataset.buyHousing))){save();clock.reset();render();open();toast('ที่พักใหม่มีภาระที่ต้องดูแลทุกปี')}});if($('#sellHousing'))$('#sellHousing').onclick=()=>{modal(`<h2>ส่งต่อที่พักหลังนี้?</h2><p>รับสุทธิ ${num(Housing.value(s))} ทองหลังหักค่าธรรมเนียม แล้วกลับไปจ่ายค่าที่พักตามแผนเดิม</p><button class="secondary" id="keepHousing">เก็บไว้</button><button class="secondary" id="confirmSellHousing">ขายที่พัก</button>`);$('#keepHousing').onclick=open;$('#confirmSellHousing').onclick=()=>{if(Housing.sell(s)){save();clock.reset();render();open()}}};document.querySelectorAll('[data-home-preview]').forEach(c=>paint(c,s,Number(c.dataset.homePreview)))}
 function paint(canvas,s,tier){const c=canvas.getContext('2d'),p=Ecology.profile(s);c.imageSmoothingEnabled=false;c.fillStyle=p.water?'#8caeb0':p.habitat==='cave'?'#8e9b83':'#b8c6ab';c.fillRect(0,0,160,72);c.fillStyle=p.water?'#637f82':'#747b5b';c.fillRect(0,58,160,14);if(s.race!==0&&p.strict){const w=50+tier*18,x=(160-w)/2;c.fillStyle='#63766b';for(let k=0;k<6;k++)c.fillRect(x+k*w/6,36-Math.min(k,5-k)*5,w/6+1,23+Math.min(k,5-k)*5);c.fillStyle='#344f4b';c.fillRect(x+12,41,w-24,17);for(let k=0;k<=tier;k++){c.fillStyle='#b3c5a0';c.fillRect(x+17+k*19,47,4,4)}return}const w=42+tier*20,x=(160-w)/2;c.fillStyle=['#d0bf92','#ddc9a1','#d9c9b3','#d3c3a6','#e2d4b4'][tier];c.fillRect(x,30-tier*3,w,29+tier*3);c.fillStyle='#6c685a';c.fillRect(x-5,24-tier*3,w+10,7);for(let k=0;k<=tier;k++){c.fillStyle='#6d8c89';c.fillRect(x+7+k*20,35-tier*3,9,9);c.fillStyle='#c6b476';c.fillRect(x+7+k*20,40-tier*3,9,2)}c.fillStyle='#68654f';c.fillRect(76,46,10,13);if(tier>=2){c.fillStyle='#91a084';c.fillRect(x-8,43,7,17);c.fillRect(x+w+1,43,7,17)}if(tier>=3){c.fillStyle='#aaa08b';c.fillRect(x-7,37,5,22);c.fillRect(x+w+2,37,5,22)}if(tier===4){c.fillStyle='#8e805f';c.fillRect(23,51,3,12);c.fillRect(134,51,3,12)}}
 function bind(){if($('#openHousing'))$('#openHousing').onclick=open}
 return {panel,open,paint,bind};
})();
